// Mapea cada lead de Supabase a las columnas de Airtable (mismos nombres que el workflow por webhook).
const b = $json;
const issues = Array.isArray(b.top_issues) ? b.top_issues : (typeof b.top_issues === 'string' ? JSON.parse(b.top_issues || '[]') : []);
return {
  json: {
    'ID': b.id,
    'Fecha': new Date(b.created_at).toISOString(),
    'Nombre': b.name,
    'Email': b.email,
    'Empresa': b.company || '',
    'URL auditada': b.audited_url,
    'Puntuación': b.score === null ? null : Number(b.score),
    'Nota': b.grade,
    'Errores': Number(b.fails),
    'Mejoras': Number(b.warnings),
    'Problemas principales': issues.map(i => `• ${i.label} (${i.category}): ${i.message}`).join('\n'),
    'Consentimiento marketing': !!b.marketing_consent,
    'Informe online': b.report_url || '',
  },
};
